      "type": "adjacent",
      "severity": "manageable",
      "rationale": "QuoteWave provides SMB quoting and invoicing, which is an adjacent workflow to Cadence's job and customer management platform. Both target SMB service businesses and natural product expansion by either company could create direct competition."
    },
    {
      "company": "InspectAI",
      "type": "adjacent",
      "severity": "manageable",
      "rationale": "InspectAI serves property inspection, a field service vertical that Cadence's scheduling and dispatch platform could expand into. Shared vertical and potential customer overlap among field service SMBs."
    },
    {
      "company": "RouteIQ",
      "type": "adjacent",
      "severity": "manageable",
      "rationale": "RouteIQ handles last-mile delivery logistics including routing and dispatch, which overlaps with Cadence's dispatch and job scheduling capabilities. Both serve businesses with field-based crews and share technical adjacency in route optimization."
    }
  ]
}
